SELECT COALESCE(SUM(change_amount), 0)
FROM user_wallet_record
WHERE wallet_id = #{walletId}
  AND status = 1
  AND change_amount > 0
  AND DATE(create_time) = #{dateParam}

SELECT COALESCE(SUM(change_amount), 0)
FROM user_wallet_record
WHERE wallet_id = #{walletId}
  AND status = 1
  AND change_amount > 0
  AND create_time >= #{startAt}
  AND create_time < #{endAt}
